      "reference_evidence": "",
      "candidate_evidence": "",
      "shared_event_ko": "",
      "conflicts_ko": [
        "참조는 과학자의 신체 부위(머리) 움직임 이상을 지적하나, 후보는 카메라 앵글 및 연출 요구사항 불일치를 지적함"
      ],
      "reason_ko": "참조의 불만 사항은 과학자 머리의 부자연스러운 움직임인 반면, 후보는 프롬프트 대비 카메라 앵글 다양성 결여를 다루므로 대상과 불만 내용이 완전히 다릅니다.",
      "event_link": "distinct_events",
      "separation_basis": "different_entity"
    }
  ]
}

